<?php require_once __DIR__.'/../config/config.php'; require __DIR__.'/includes/header.php'; $pdo=db(); $counts=['products'=>$pdo->query('SELECT COUNT(*) FROM products WHERE active=1')->fetchColumn(),'orders'=>$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'pending'=>$pdo->query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn(),'messages'=>$pdo->query("SELECT COUNT(*) FROM messages WHERE status='new'")->fetchColumn()]; $recent=$pdo->query('SELECT * FROM orders ORDER BY id DESC LIMIT 8')->fetchAll(); ?><div class="content"><h1>Dashboard</h1><p class="muted">Visão geral da loja e operações.</p><div class="grid" style="margin:20px 0"><?php foreach($counts as $k=>$v):?><div class="card"><div class="muted"><?=e(['products'=>'Produtos ativos','orders'=>'Pedidos','pending'=>'Pagamentos pendentes','messages'=>'Mensagens novas'][$k])?></div><div class="stat"><?=e($v)?></div></div><?php endforeach;?></div><div class="panel"><h2>Pedidos recentes</h2><table class="table"><tr><th>#</th><th>Cliente</th><th>Total</th><th>Status</th><th>Data</th></tr><?php foreach($recent as $o):?><tr><td><a href="orders.php?id=<?=$o['id']?>">#<?=$o['id']?></a></td><td><?=e($o['customer_name'])?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/includes/footer.php';
